    if (key is! String) return null;
    final config = _store.overrideFor(key);
    if (config == null) return null;
    return [
      ModelRef(
        provider: config.providerKind,
        modelId: config.modelId,
        apiKeyName: config.apiKeyName,
        baseUrl: config.baseUrl,
