    // endpoint-aware UI never reads an uninitialized late field.
    _activeBaseUrl = _agent.state.model.baseUrl;
    _activeApiKey = '';
    _wireImageDropNotice();
    _wireTextOnlyImageDropNotice();
    _wireDeliverySloNotice();
    _redactor = redactor;

