    contextWindow: contextWindow,
    maxTokens: maxTokens,
    supportsImages: supportsImages,
  );

  Model toModel() => Model(
    id: modelId,
    name: modelId,
    api: providerKind,
    provider: providerKind,
    baseUrl: baseUrl,
    contextWindow: contextWindow,
    maxTokens: maxTokens,
