             sessionsRoot: sessionsRoot,
             // Resume diagnostics: session-open timings as `resume_timing`
             // lines in the app debug log (logs/app.log).
             timingLog: (line) => AppLog.i('resume', line),
             presenceStore: FileSessionPresenceStore(
               env: env,
               root: sessionsRoot,
