/// The parsed owner cap, or null (absent — uncapped).
int? loadAppContextWindowCap([String? projectDir]) {
  try {
    // Project-level .fah/config.yaml wins (it travels in git).
    if (projectDir != null) {
      final project = loadProjectContextWindowCap(projectDir);
